import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec4, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const owned = [];
  const timelines = [];
  const loadedTextures = [];
  let disposed = false;

  const makeGradientMaterial = (topColor, bottomColor, accentAmount = 0) => {
    const material = new MeshBasicNodeMaterial();
    const vertical = smoothstep(0.0, 1.0, uv().y);
    const gradient = mix(color(bottomColor), color(topColor), vertical);
    const accented = mix(
      gradient,
      color('#ff2a38'),
      smoothstep(0.82, 1.0, uv().y).mul(accentAmount)
    );

    material.colorNode = vec4(accented, 1.0);
    material.needsUpdate = true;
    owned.push(material);
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = makeGradientMaterial('#16161d', '#0b0b10', 0.035);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  backdrop.userData.__ownedResource = true;
  root.add(backdrop);
  owned.push(backdropGeometry);

  const cardGeometry = new PlaneGeometry(2.35, 1.4);
  const cardMaterial = makeGradientMaterial('#16161d', '#0b0b10', 0.08);
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.set(0, 0, -0.35);
  card.userData.__ownedResource = true;
  root.add(card);
  owned.push(cardGeometry);

  const accentGeometry = new PlaneGeometry(0.07, 1.12);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  accentMaterial.needsUpdate = true;
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-1.02, 0, -0.18);
  accent.userData.__ownedResource = true;
  root.add(accent);
  owned.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = String(item.text ?? '');
    const typography = item.typography ?? {};
    const label = ctx.fontAtlas.createText(text, {
      fontSize: typography.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: typography.letterSpacingPx
    });

    label.position.set(-0.84, -0.06, -0.05);
    label.userData.__fontAtlasText = true;
    root.add(label);
  }

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      loadedTextures.push(texture);
      if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }

      const imageGeometry = new PlaneGeometry(0.86, 0.86);
      const imageMaterial = new MeshBasicNodeMaterial({
        map: texture,
        transparent: true,
        opacity: 0.16,
        depthWrite: false
      });
      const image = new Mesh(imageGeometry, imageMaterial);
      image.position.set(0.62, 0.02, -0.08);
      image.userData.__ownedResource = true;
      root.add(image);
      owned.push(imageGeometry, imageMaterial);
    }).catch(() => {});
  }

  const entryScale = root.scale.clone();
  root.scale.set(
    entryScale.x * 0.96,
    entryScale.y * 0.96,
    entryScale.z * 0.96
  );

  const entrance = gsap.timeline();
  entrance.fromTo(
    root.position,
    { y: root.position.y + 0.2 },
    {
      y: root.position.y,
      duration: 0.7,
      ease: 'power3.out'
    }
  ).to(
    root.scale,
    {
      x: entryScale.x,
      y: entryScale.y,
      z: entryScale.z,
      duration: 0.9,
      ease: 'power4.out'
    },
    '<'
  );
  timelines.push(entrance);

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const texture of loadedTextures) {
      texture.dispose?.();
    }

    for (const resource of owned) {
      resource.dispose?.();
    }

    root.clear();
  };

  return root;
}
